package com.expense.controller;
import com.expense.dto.ClaimDtos.*; import com.expense.service.ClaimService; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
import com.expense.service.ClaimCsvService; import org.springframework.http.*;
import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag;
@RestController @RequestMapping("/api/manager") @Tag(name="Manager",description="Review and export claims assigned to the authenticated manager") @SecurityRequirement(name="bearerAuth")
public class ManagerController {
 private final ClaimService service; private final ClaimCsvService csv; public ManagerController(ClaimService s,ClaimCsvService csv){service=s;this.csv=csv;}
 @GetMapping("/claims") @Operation(summary="List assigned claims",description="Filters claims assigned to the signed-in manager by status, employee name or email, and inclusive expense date range.") public Page<ClaimResponse> all(Authentication a,@RequestParam(required=false)String status,@RequestParam(required=false)String employee,@RequestParam(required=false)String from,@RequestParam(required=false)String to,Pageable p){return service.managerList(a.getName(),status,employee,from,to,p);}
 @GetMapping(value="/claims/export.csv",produces="text/csv") @Operation(summary="Export assigned claims as CSV",description="Exports all matching claims assigned to the signed-in manager, using the same filters as the claims list.") public ResponseEntity<byte[]> export(Authentication a,@RequestParam(required=false)String status,@RequestParam(required=false)String employee,@RequestParam(required=false)String from,@RequestParam(required=false)String to){byte[] body=csv.export(a.getName(),status,employee,from,to);return ResponseEntity.ok().contentType(MediaType.parseMediaType("text/csv;charset=UTF-8")).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=expense-claims.csv").body(body);}
 @PatchMapping("/claims/{id}/review") @Operation(summary="Approve or reject a claim",description="A comment is required for rejection.") public ClaimResponse review(Authentication a,@PathVariable Long id,@Valid @RequestBody ReviewRequest r){return service.review(a.getName(),id,r);}
}
